long val_open_max;
long val_page_size;

// Retrieve runtime limits using sysconf()
// _SC_OPEN_MAX: Max files process can open
val_open_max = sysconf(_SC_OPEN_MAX);

// _SC_PAGESIZE: System memory page size (bytes)
val_page_size = sysconf(_SC_PAGESIZE);

if (val_open_max == -1) {
    // Limit is indeterminate or unsupported
    // Check errno for failure
}

// Portable use of runtime limits
size_t buffer_size = val_page_size * 4;
